<?php use App\Core\Security; use App\Core\Auth; ?>
<section class="panel narrow"><div class="panel-header"><h2>Whitelist oder SteamID-Liste importieren</h2><p>Unterstützt TXT, CSV, JSON, JSONC, SwiftlyS2 <span class="mono">permissions.jsonc</span> und CounterStrikeSharp-Adminlisten. SteamID64s werden unabhängig vom restlichen Dateiformat erkannt.</p></div>
<form method="post" action="/players/import" enctype="multipart/form-data" class="form-stack"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrfToken())?>"><label>Datei hochladen<input type="file" name="import_file" accept=".txt,.csv,.json,.jsonc,text/plain,application/json"></label><label>oder Inhalt einfügen<textarea name="content" rows="9" placeholder="7656119...&#10;7656119..."></textarea></label><div class="form-grid"><label>Community-Rolle für neue Einträge<select name="default_role"><?php $maxLevel=Auth::GAME_ROLE_LEVELS[Auth::maxCommunityRole()]??1;foreach($roles as $rk=>$label):if((Auth::GAME_ROLE_LEVELS[$rk]??0)>$maxLevel)continue;?><option value="<?=$rk?>"><?=Security::e($label)?></option><?php endforeach;?></select></label><label>Optional einem Server zuordnen<select name="server_id"><option value="0">Keine Serverzuordnung</option><?php foreach($servers as $s):?><option value="<?=$s['id']?>"><?=Security::e($s['name'])?></option><?php endforeach;?></select></label></div><label>Servergruppe bei Zuordnung<select name="server_role"><?php foreach($roles as $rk=>$label):?><option value="<?=$rk?>"><?=Security::e($label)?></option><?php endforeach;?></select></label><?php if($steamConfigured&&Auth::can('players.steam.sync')):?><label class="checkbox-line"><input type="checkbox" name="sync_steam" value="1" checked> Steam-Profile nach Import automatisch abrufen</label><?php endif;?><button class="btn btn-primary">Importieren</button></form></section>

<?php if($servers):?><section class="panel narrow"><div class="panel-header"><h2>Datei direkt von einem Gameserver einlesen</h2><p>Geeignet für bestehende Whitelist-Dateien. Es werden nur erkannte SteamID64s importiert; der Dateiinhalt wird nicht dauerhaft gespeichert.</p></div><form method="post" action="/players/import-remote" class="form-stack"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrfToken())?>"><label>Server<select name="server_id" required><?php foreach($servers as $s):?><option value="<?=$s['id']?>"><?=Security::e($s['name'])?></option><?php endforeach;?></select></label><label>Remote-Pfad<input class="mono" type="text" name="remote_path" placeholder="game/csgo/addons/swiftlys2/configs/permissions.jsonc" required></label><div class="form-grid"><label>Community-Rolle für neue Einträge<select name="default_role"><?php foreach($roles as $rk=>$label):?><option value="<?=$rk?>"><?=Security::e($label)?></option><?php endforeach;?></select></label><label>Servergruppe<select name="server_role"><?php foreach($roles as $rk=>$label):?><option value="<?=$rk?>"><?=Security::e($label)?></option><?php endforeach;?></select></label></div><?php if($steamConfigured&&Auth::can('players.steam.sync')):?><label class="checkbox-line"><input type="checkbox" name="sync_steam" value="1" checked> Steam-Profile anschließend abrufen</label><?php endif;?><button class="btn btn-primary">Remote-Datei importieren</button></form></section><?php endif;?>
